learn=[('Understand dual-write storage', 'The SDK writes locally first and then mirrors transcript batches through append. A store is a mirror, not a replacement for local execution files.'), ('Use the SDK memory store', 'Run two actual queries with one InMemorySessionStore instance. The second loads the first conversation. The memory store disappears when that process exits.'), ('Build an ordered file adapter', 'Implement append and load, preserve opaque entry payloads and ordering, deduplicate UUID retries, and validate the adapter with Anthropic’s official 13-contract suite.'), ('Resume after a worker exits', 'Run a new process with the same working directory, a clean SDK configuration and the shared adapter. The restart test removes the source local config before resuming.'), ('Inspect and manage stored sessions', 'Use native listSessions, getSessionMessages and deleteSession helpers with the adapter. Optional summaries speed listing; subkeys preserve transcript namespaces.'), ('Observe failure and option boundaries', 'Inspect actual mirror_error events, missing-store fallback and startup conflicts. persistSession false and file checkpointing cannot be combined with a store. This lab simulates hosts locally.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3141\n# Windows only, if needed:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Use Node.js 24+, model API access and available credit. Windows may require Git Bash. No cloud storage account or GitHub token is required. Python is needed only to regenerate pages.', 'node --version\nnpm --version'), ('Install and create .env', 'Install locked dependencies. Preserve an existing .env and configure your own API key privately. The npm scripts load it into the same process that runs the worker.', 'cd .\\agent-sdk\\lesson41-session-storage\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start and navigate', 'Keep the terminal open. Use all five navigation buttons for learning goals, setup, UML, source walkthrough and the live lab.', 'npm start\n# http://127.0.0.1:3141'), ('Compare memory, file and restart', 'Memory reuses one SDK-provided memory store in one worker. File starts a fresh worker and adapter instance. Restart also removes the source local config before the clean target loads stored history. Both simulated hosts use the SAME working directory.', 'npm run sample:env -- memory\nnpm run sample:env -- file\nnpm run sample:env -- restart'), ('Inspect optional store operations', 'Continue selects the latest stored session. Catalog exposes native session metadata and messages. Delete uses the actual SDK helper against the external store; it does not erase the source local copy.', 'npm run sample:env -- continue\nnpm run sample:env -- catalog\nnpm run sample:env -- delete'), ('Observe failures and validate the adapter', 'Failure injects an external append outage and records actual mirror_error events while the local query can finish. Conflicts exercises two real SDK startup rejections. Missing demonstrates an unknown-store lookup with a clean local config, then a healthy fresh run. Tests include the official 13-contract suite plus retry, ordering and isolation checks.', 'npm run sample:env -- failure\nnpm run sample:env -- conflicts\nnpm run sample:env -- missing\nnpm test')]
specs=[('Validate the storage experiment', 'src/modes.ts', 'export function validateConfig', 'Accept only fixed classroom scenarios. A browser request cannot supply arbitrary session IDs, filesystem paths or backend credentials.', 0, 1, 7), ('Implement the mirror append contract', 'src/worker.ts', 'async append(key, entries)', 'The real SDK calls this adapter wrapper after local transcript writes. Record actual batch keys and counts, then pass opaque entries to the selected backing store.', 2, 4, 9), ('Preserve order and retry identity', 'src/store.ts', 'const seen = new Set', 'Preserve arrival order and use UUIDs as retry identities. Entries without UUIDs remain append-only metadata; do not discard or reinterpret their payloads.', 1, 4, 11), ('Load opaque stored entries', 'src/store.ts', 'load(key: SessionKey)', 'Return the complete ordered entry array or null for an unknown key. The SDK materializes the returned history before resuming.', 4, 2, 6), ('Use the SDK memory store', 'src/worker.ts', 'const backing =', 'The quick-start experiment uses the real SDK InMemorySessionStore. File experiments create a new file-backed adapter instance in each worker.', 1, 4, 5), ('Attach storage and session selectors', 'src/worker.ts', 'sessionStore: store,', 'Pass the actual adapter to query. Eager flushing exposes append events; resume or continue selects previously stored history. The working directory must match.', 1, 2, 7), ('Capture the actual native session ID', 'src/worker.ts', 'message.type === "system" && message.subtype === "init"', 'Capture system/init identifiers and actual result IDs. New worker process IDs make process boundaries distinct from conversation identity.', 2, 1, 6), ('Remove the source local config', 'src/agent.ts', 'await w.eraseSource();', 'The restart experiment removes only its own temporary source config. The external adapter stays outside that directory and survives until evidence collection finishes.', 1, 3, 5), ('Resume in the clean target worker', 'src/agent.ts', 'if (c.mode === "file" || c.mode === "restart")', 'Start a new Node worker with a clean config directory, the same project working directory and the stored session ID. Actual load events prove retrieval through the adapter.', 1, 2, 6), ('Read the native store catalog', 'src/worker.ts', 'const sessions = await listSessions', 'List sessions through the SDK helper with sessionStore attached, then retrieve their messages. No model query is needed for catalog inspection.', 4, 1, 8), ('Delete through the SDK helper', 'src/worker.ts', 'await deleteSession(request.resume!', 'Delete the external main transcript and its subkeys through the actual SDK helper. The original local transcript is a separate copy.', 1, 4, 5), ('Surface a mirror outage', 'src/worker.ts', 'message.type === "system" && message.subtype === "mirror_error"', 'Capture native mirror_error system messages after bounded failed append attempts. A successful local result does not imply external durability.', 2, 0, 5), ('Exercise incompatible options', 'src/worker.ts', 'persistSession: request.conflict', 'The conflicts scenario deliberately combines sessionStore with persistSession false or file checkpointing. Actual SDK startup exceptions are shown, followed by a valid run.', 1, 2, 6)]
document('/','Session storage <em>beyond disk.</em>','Mirror real transcripts, restore from a shared adapter and inspect failures.','<div class="flow"><div><b>01 · Mirror</b><p>Local JSONL → append</p></div><span>→</span><div><b>02 · Persist</b><p>Opaque ordered entries</p></div><span>→</span><div><b>03 · Restore</b><p>Load → resume history</p></div></div><section class="panel" id="controls"><h2>Explore external session storage</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Storage experiment</label><select id="mode"><option value="memory">Memory store · SDK quick start</option><option value="file">File adapter · resume from the store</option><option value="restart">Worker restart · erase source local config</option><option value="continue">Continue · latest stored session</option><option value="catalog">Catalog · inspect stored messages</option><option value="failure">Mirror outage · observe best-effort writes</option><option value="conflicts">Conflicts · invalid persistence and checkpoints</option><option value="missing">Missing session · fallback and recovery</option><option value="delete">Delete · remove the external transcript</option></select><button id="run" class="primary" disabled>Run storage experiment →</button><p class="meta">Actual SDK queries and adapter calls. Two LOCAL workers/configurations simulate a host change; no S3, Redis or Postgres service is provisioned. The file adapter supports one sequential writer. Temporary classroom data is removed after evidence capture. SDK threshold: $0.25 per query.</p></section><section class="step" id="picker-panel"><h2>Inspect an actual stored session</h2><p id="choice-status" class="note">Choose a catalog entry to inspect its messages. This does not invoke the model.</p><label for="session-picker">Native SDK store catalog</label><select id="session-picker"><option>No stored sessions yet</option></select><button id="resume-session" style="display:none!important" hidden disabled>Resume selected session</button></section><div class="workspace"><section class="panel" id="chat-panel"><h2 id="status" aria-live="polite">Ready</h2><div id="conversation"></div></section><section class="panel" id="option-panel"><h2>Host configuration</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Each query and its exact store/resume/continue options appear in the observation selector.</p></section></div><section class="step" id="comparison-panel"><h2>Actual query responses</h2><div class="grid" id="branch-cards"></div></section><section class="step" id="results-panel"><h2>Actual results, session IDs and processes</h2><div class="table"><table><thead><tr><th>Query</th><th>Stage</th><th>Node PID</th><th>Status</th><th>session_id</th><th>Result text</th></tr></thead><tbody id="result-history"></tbody></table></div><pre class="json-view"><code id="latest-result" class="language-json">{}</code></pre></section><section class="step" id="catalog-panel"><h2>Native SDK session catalog</h2><pre class="json-view"><code id="catalog" class="language-json">[]</code></pre></section><section class="step" id="messages-panel"><h2>Messages from the selected transcript</h2><pre class="json-view"><code id="messages" class="language-json">{}</code></pre><p>This is actual getSessionMessages output, read without a model request.</p></section><section class="step" id="storage-panel"><h2>Store and local transcript evidence</h2><pre class="json-view"><code id="storage" class="language-json">{}</code></pre><p>Inspect actual external rows, local JSONL paths and native exceptions. The lab cleans up all temporary classroom storage after collecting evidence.</p></section><section class="step" id="observation-panel"><h2>Inspect actual query and worker events</h2><label for="observation-select">Observed arrival sequence</label><select id="observation-select"><option>No observations yet</option></select><pre class="json-view"><code id="selected-observation" class="language-json">{}</code></pre></section><section class="step" id="evidence-panel"><h2>Independent run evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><button id="download">Download actual observations</button></section>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Understand dual-write storage, adapter contracts and store-backed resume.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your .env configuration</h2>'+snippet(env,'dotenv')+'<p>Only your model key is required. Keep it local and restart after edits. Existing shell variables take precedence.</p></section><section class="note"><h3>Troubleshooting</h3><p>Use Node 24+, API credit and a supported model. Configure Git Bash on Windows if requested. If the port is occupied, use the printed existing-app URL or change PORT. All experiments finish automatically. Select any saved catalog entry to inspect actual messages without a model query. Change PORT if 3141 is occupied.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install the SDK, configure your key and run the classroom comparisons.',body)
steps=[];arrows=[];lanes=['Student UI','TypeScript host','SDK worker process','Local JSONL','SessionStore adapter']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
